scriptdefs
= BattleFrontier_BattlePikeLobby_EventScript_LostChallenge
lockall
msgbox	Deine Herausforderung ist beendet…Ich halte deine Ergebnisse fest. Bitte warte einen Moment…
waitmessage
frontier_checkairshow
frontier_set FRONTIER_DATA_BATTLE_NUM 0
pike_set PIKE_DATA_WIN_STREAK_ACTIVE FALSE
special LoadPlayerParty
special HealPlayerParty
pike_resethelditems
pike_save 0
playse SE_SAVE
waitse
msgbox	Wir freuen uns, dich bei anderer Gelegenheit wiederzusehen…
closemessage
setvar VAR_TEMP_CHALLENGE_STATUS 255
releaseall
end
= BattleFrontier_BattlePikeLobby_EventScript_WonChallenge
lockall
frontier_isbrain
goto_if_eq VAR_RESULT TRUE BattleFrontier_BattlePikeLobby_EventScript_DefeatedQueen
msgbox	Du hast die Herausforderung gemeistert…Ich muss sagen… Du scheinst über reichlich Glück zu verfügen…
waitmessage
goto BattleFrontier_BattlePikeLobby_EventScript_GiveBattlePoints
= BattleFrontier_BattlePikeLobby_EventScript_GiveBattlePoints
msgbox	Als Anerkennung für dein erstaunliches Glück erhältst du diese Kampfpunkte…
frontier_givepoints
msgbox	PLAYER hat STR_VAR_1 Kampfpunkt(e) erhalten.
frontier_checkairshow
pike_get PIKE_DATA_TOTAL_STREAKS
addvar VAR_RESULT 1
pike_set PIKE_DATA_TOTAL_STREAKS VAR_RESULT
special LoadPlayerParty
special HealPlayerParty
pike_resethelditems
msgbox	Ich halte deine Ergebnisse fest. Bitte warte einen Moment…
waitmessage
pike_save 0
playse SE_SAVE
waitse
msgbox	Wir freuen uns, dich bei anderer Gelegenheit wiederzusehen…
closemessage
setvar VAR_TEMP_CHALLENGE_STATUS 255
releaseall
end
= BattleFrontier_BattlePikeLobby_EventScript_DefeatedQueen
msgbox	Glückwunsch…Du hast der PIKE QUEEN den Sieg entrissen und das Event gemeistert…
waitmessage
goto BattleFrontier_BattlePikeLobby_EventScript_GiveBattlePoints
= BattleFrontier_BattlePikeLobby_EventScript_QuitWithoutSaving
special HealPlayerParty
pike_resethelditems
lockall
msgbox	Verzeih bitte, aber…Du hast beim letzten Mal nicht gespeichert, bevor du deine Herausforderung abgebrochen hast.Deshalb wurde deine bisherige Herausforderung annulliert. Das tut mir leid…
closemessage
pike_set PIKE_DATA_WIN_STREAK 0
pike_set PIKE_DATA_WIN_STREAK_ACTIVE FALSE
frontier_set FRONTIER_DATA_CHALLENGE_STATUS 0
setvar VAR_TEMP_CHALLENGE_STATUS 255
releaseall
end
= BattleFrontier_BattlePikeLobby_EventScript_GetChallengeStatus
frontier_getstatus
end
= BattleFrontier_BattlePikeLobby_EventScript_Beauty
msgbox	Hör mal! Hör mal!Findest du nicht auch, dass die besonderen Fähigkeiten von POKéMON hier nützlich sein könnten?
end
= BattleFrontier_BattlePikeLobby_EventScript_Twin
msgbox	Ich habe die Herausforderung jetzt schon 10 Mal geschafft, aber ich musste noch nie gegen einen TRAINER kämpfen.
end
= BattleFrontier_BattlePikeLobby_EventScript_Hiker
msgbox	Argh! Ich habe meine Chance vertan! Ich war nur einen Raum vom Ziel entfernt!Hier solltest du besser auf Gift, Frost und Ähnliches achtgeben.
end
= BattleFrontier_BattlePikeLobby_EventScript_Attendant
lock
faceplayer
setvar VAR_FRONTIER_FACILITY FRONTIER_FACILITY_PIKE
setvar VAR_FRONTIER_BATTLE_MODE FRONTIER_MODE_SINGLES
special SavePlayerParty
msgbox	Hier wird das Glück von TRAINERN auf die Probe gestellt…Willkommen bei der BATTLE PIKE…Ich bin dein Führer für die BATTLE PIKE…
goto BattleFrontier_BattlePikeLobby_EventScript_AskTakeChallenge
= BattleFrontier_BattlePikeLobby_EventScript_AskTakeChallenge
msgbox	Möchtest du die Battle-Choice-Herausforderung annehmen?
waitmessage
multichoice 17 6 MULTI_CHALLENGEINFO FALSE
switch VAR_RESULT
case 0 BattleFrontier_BattlePikeLobby_EventScript_TryEnterChallenge
case 1 BattleFrontier_BattlePikeLobby_EventScript_ExplainChallenge
case 2 BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
case MULTI_B_PRESSED BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
goto BattleFrontier_BattlePikeLobby_EventScript_TryEnterChallenge
= BattleFrontier_BattlePikeLobby_EventScript_TryEnterChallenge
msgbox	Du hast die Wahl zwischen zwei Klassen, Level 50 und Offenes Level. Welche möchtest du herausfordern?
waitmessage
multichoice 17 6 MULTI_LEVEL_MODE FALSE
switch VAR_RESULT
case FRONTIER_LVL_TENT BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
case MULTI_B_PRESSED BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
frontier_checkineligible
goto_if_eq VAR_0x8004 TRUE BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMons
frontier_set FRONTIER_DATA_LVL_MODE VAR_RESULT
msgbox	Bitte wähle die drei POKéMON aus, mit denen du zur Herausforderung antreten möchtest…
fadescreen FADE_TO_BLACK
call BattleFrontier_EventScript_GetLvlMode
copyvar VAR_0x8004 VAR_RESULT
setvar VAR_0x8005 FRONTIER_PARTY_SIZE
special ChoosePartyForBattleFrontier
goto_if_eq VAR_RESULT 0 BattleFrontier_BattlePikeLobby_EventScript_LoadPartyAndCancelChallenge
msgboxyesno	Before starting your Battle Choice challenge, I must save the game. Is that acceptable?
switch VAR_RESULT
case NO BattleFrontier_BattlePikeLobby_EventScript_LoadPartyAndCancelChallenge
case YES BattleFrontier_BattlePikeLobby_EventScript_SaveBeforeChallenge
case MULTI_B_PRESSED BattleFrontier_BattlePikeLobby_EventScript_LoadPartyAndCancelChallenge
goto BattleFrontier_BattlePikeLobby_EventScript_SaveBeforeChallenge
= BattleFrontier_BattlePikeLobby_EventScript_SaveBeforeChallenge
setvar VAR_TEMP_CHALLENGE_STATUS 0
setvar VAR_TEMP_1 0
frontier_set FRONTIER_DATA_SELECTED_MON_ORDER
pike_init
frontier_set FRONTIER_DATA_CHALLENGE_STATUS CHALLENGE_STATUS_SAVING
pike_set PIKE_DATA_WIN_STREAK_ACTIVE TRUE
pike_savehelditems
frontier_set FRONTIER_DATA_PAUSED FALSE
special LoadPlayerParty
closemessage
delay 2
call Common_EventScript_SaveGame
setvar VAR_TEMP_CHALLENGE_STATUS 255
pike_savehelditems
goto_if_eq VAR_RESULT 0 BattleFrontier_BattlePikeLobby_EventScript_CancelChallengeSaveFailed
special SavePlayerParty
frontier_setpartyorder FRONTIER_PARTY_SIZE
msgbox	Bitte komm hier entlang…
closemessage
frontier_settrainers
call BattleFrontier_BattlePikeLobby_EventScript_WalkToCorridor
special HealPlayerParty
call BattleFrontier_BattlePike_EventScript_CloseCurtain
warpsilent BattleFrontier_BattlePikeCorridor 6 7
setvar VAR_TEMP_CHALLENGE_STATUS 0
waitstate
end
= BattleFrontier_BattlePike_EventScript_CloseCurtain
playse SE_PIKE_CURTAIN_CLOSE
special CloseBattlePikeCurtain
waitse
return
= BattleFrontier_BattlePikeLobby_EventScript_WalkToCorridor
applymovement LOCALID_PIKE_LOBBY_ATTENDANT BattleFrontier_BattlePikeLobby_Movement_AttendantWalkToCorridor
applymovement LOCALID_PLAYER BattleFrontier_BattlePikeLobby_Movement_PlayerWalkToCorridor
waitmovement 0
return
= BattleFrontier_BattlePikeLobby_EventScript_CancelChallengeSaveFailed
frontier_set FRONTIER_DATA_CHALLENGE_STATUS 0
goto BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
= BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
msgbox	Wir freuen uns, dich bei anderer Gelegenheit wiederzusehen…
goto BattleFrontier_BattlePikeLobby_EventScript_EndCancelChallenge
= BattleFrontier_BattlePikeLobby_EventScript_EndCancelChallenge
release
end
= Common_EventScript_SaveGame
special SaveGame
return
= BattleFrontier_BattlePikeLobby_EventScript_LoadPartyAndCancelChallenge
special LoadPlayerParty
goto BattleFrontier_BattlePikeLobby_EventScript_CancelChallenge
= BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMons
switch VAR_RESULT
case FRONTIER_LVL_50 BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMonsLv50
case FRONTIER_LVL_OPEN BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMonsLvOpen
goto BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMonsLv50
= BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMonsLv50
msgbox	Verzeih bitte, aber…Du hast keine drei zugelassenen POKéMON für das Battle-Choice-Event.Du brauchst drei unterschiedliche POKéMON mit höchstens Level 50, um anzutreten.Sie müssen außerdem unterschiedliche Items bei sich tragen.EGGSSTR_VAR_1 nicht zugelassen.Sprich mich an, sobald du bereit bist…
goto BattleFrontier_BattlePikeLobby_EventScript_EndCancelChallenge
= BattleFrontier_BattlePikeLobby_EventScript_NotEnoughValidMonsLvOpen
msgbox	Verzeih bitte, aber…Du hast keine drei zugelassenen POKéMON für das Battle-Choice-Event.Du brauchst drei unterschiedliche POKéMON, um anzutreten.Sie müssen außerdem unterschiedliche Items bei sich tragen.EGGSSTR_VAR_1 nicht zugelassen.Sprich mich an, sobald du bereit bist…
goto BattleFrontier_BattlePikeLobby_EventScript_EndCancelChallenge
= BattleFrontier_BattlePikeLobby_EventScript_ExplainChallenge
msgbox	Hier veranstalten wir ein Event namens Battle Choice.Die Regeln der Battle Choice sind sehr einfach…Wähle einen von drei Wegen und bahne dir deinen Weg zum Zielraum am Ende der BATTLE PIKE. So einfach ist das.Was jedoch auf dem gewählten Weg geschieht, hängt ganz vom Glück des Herausforderers ab…Erreichst du das Ziel, wirst du mit Kampfpunkten belohnt.Wenn du deine Herausforderung unterbrechen möchtest, wende dich bitte an unser Personal in den großen Räumen unterwegs.Speicherst du nicht, bevor du unterbrichst, wirst du disqualifiziert.
goto BattleFrontier_BattlePikeLobby_EventScript_AskTakeChallenge
signs
1 3	Die Regeln der Battle Choice sind hier aufgelistet.
